{"implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    memory = []
    signatures = []
    if capacity <= 0:
        signatures = [t['signature'] for t in trials]
        return {'memory': [], 'signatures': signatures}
    for i, trial in enumerate(trials):
        sig = trial['signature']
        signatures.append(sig)
        idx = -1
        for j, entry in enumerate(memory):
            if entry['signature'] == sig:
                idx = j
                break
        if idx != -1:
            del memory[idx]
        else:
            if len(memory) >= capacity:
                memory.pop(0)
        memory.append({
            'last_trial': i,
            'reflection': trial['reflection'],
            'signature': sig,
            'success': trial['success']
        })
    return {'memory': memory, 'signatures': signatures}"}
